code='''def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    # Each separated nonzero construction is one object. Within it, nested colors
    # are ordered by the area of their bounding boxes; reverse that order.
    seen=set(); out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]!=0:
                        seen.add(q); stack.append(q)
            colors={grid[y][x] for y,x in cells}
            boxes={}
            for color in colors:
                pts=[(y,x) for y,x in cells if grid[y][x]==color]
                boxes[color]=(min(y for y,x in pts),max(y for y,x in pts),min(x for y,x in pts),max(x for y,x in pts))
            order=sorted(colors,key=lambda z: ((boxes[z][1]-boxes[z][0]+1)*(boxes[z][3]-boxes[z][2]+1)),reverse=True)
            mapping={old:new for old,new in zip(order,reversed(order))}
            for y,x in cells: out[y][x]=mapping[grid[y][x]]
    return out
